style.css:
/* ==============================================
   FORMULA TIMER — GRAPHITE
   Quiet surfaces. Clean hierarchy. Less noise.
   ============================================== */

/* PAGE */

html,
body {
  background: #101010 !important;
  color: #dedede !important;
  font-family: "Segoe UI", Arial, sans-serif !important;
  font-size: 13px !important;
}

/* NAVIGATION */

header,
nav,
[role="navigation"] {
  background: #141414 !important;
  border-color: #292929 !important;
  box-shadow: none !important;
}

a {
  text-decoration: none !important;
}

/* HEADINGS */

h1, h2, h3, h4, h5, h6 {
  color: #e8e8e8;
  font-family: "Segoe UI", Arial, sans-serif !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
}

/* LEADERBOARD TABLE */

table {
  border-collapse: separate !important;
  border-spacing: 0 3px !important;
  background: #101010 !important;
  color: #dedede !important;
  font-variant-numeric: tabular-nums;
}

thead th {
  background: #151515 !important;
  color: #999999 !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  text-transform: uppercase;
  letter-spacing: 0.35px;
  border-color: #292929 !important;
  box-shadow: none !important;
}

/* Neutralize loud row fills */

tbody tr,
tbody tr td {
  background-color: #1b1b1b !important;
  color: #dedede;
  border-color: #1b1b1b !important;
  box-shadow: none !important;
}

/* Soft alternating rows */

tbody tr:nth-child(even),
tbody tr:nth-child(even) td {
  background-color: #202020 !important;
}

/* Gentle hover */

tbody tr:hover,
tbody tr:hover td {
  background-color: #292929 !important;
}

/* Driver names: remove pill-like styling */

tbody td span,
tbody td a {
  box-shadow: none !important;
}

/* Keep timing values crisp */

td,
th {
  font-variant-numeric: tabular-nums;
}

/* Keep sector graphics visible, without recolouring them.
   Existing sector bars retain their original colours. */

/* Remove unnecessary shadows and gradients */

* {
  text-shadow: none;
  box-shadow: none;
}

/* Controls */

button,
input,
select,
textarea {
  font-family: "Segoe UI", Arial, sans-serif !important;
  box-shadow: none !important;
}

button {
  border-radius: 5px;
}

/* Subtle separators */

hr {
  border: none;
  border-top: 1px solid #2a2a2a;
}

/* Scrollbar styling intentionally omitted */

/* MOBILE */

@media screen and (max-width: 768px) {
  html,
  body {
    font-size: 12px !important;
  }

  th,
  td {
    padding-left: 7px;
    padding-right: 7px;
  }
}
